11	// FusedAddRmsnorm op_host — tiling calculation + EXEC_KERNEL_CMD launch
12	
13	#include <algorithm>
14	#include <cstdint>
15	
16	#include <torch/extension.h>
17	#include <torch/library.h>
18	
19	#include "torch_kernel_helper.h"
20	#include "tiling/platform/platform_ascendc.h"
21	
22	#include "aclrtlaunch_fused_add_rmsnorm.h"
23	
24	// ---------------------------------------------------------------------------
25	// Tiling constants
26	// ---------------------------------------------------------------------------
27	
28	constexpr int32_t DEFAULT_BLOCK_M = 64;
29	constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;
30	
31	// ---------------------------------------------------------------------------
32	// Host function
33	// ---------------------------------------------------------------------------
34	
35	namespace ascend_kernel {
36	
37	at::Tensor fused_add_rmsnorm(
38	    const at::Tensor &hidden_states,
39	    const at::Tensor &residual,
40	    const at::Tensor &weight,
41	    double eps)
42	{
43	    TORCH_CHECK(hidden_states.dim() == 2, "hidden_states must be [M, N]");
44	    TORCH_CHECK(residual.dim() == 2, "residual must be [M, N]");
45	    TORCH_CHECK(weight.dim() == 1, "weight must be [N]");
46	    TORCH_CHECK(
47	        hidden_states.scalar_type() == at::kFloat ||
48	        hidden_states.scalar_type() == at::kHalf ||
49	        hidden_states.scalar_type() == at::kBFloat16,
50	        "hidden_states must be float32, float16, or bfloat16");
51	    TORCH_CHECK(residual.scalar_type() == hidden_states.scalar_type(),
52	        "residual must have the same dtype as hidden_states");
53	    TORCH_CHECK(weight.scalar_type() == hidden_states.scalar_type(),
54	        "weight must have the same dtype as hidden_states");
55	    TORCH_CHECK(hidden_states.is_contiguous(), "hidden_states must be contiguous");
56	    TORCH_CHECK(residual.is_contiguous(), "residual must be contiguous");
57	    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
58	    TORCH_CHECK(static_cast<int32_t>(hidden_states.sizes()[0]) == static_cast<int32_t>(residual.sizes()[0]),
59	        "hidden_states and residual batch sizes must match");
60	    TORCH_CHECK(static_cast<int32_t>(hidden_states.sizes()[1]) == static_cast<int32_t>(residual.sizes()[1]),
61	        "hidden_states and residual hidden sizes must match");
62	    TORCH_CHECK(static_cast<int32_t>(hidden_states.sizes()[1]) == static_cast<int32_t>(weight.sizes()[0]),
63	        "weight shape must match hidden_size");
64	
65	    int32_t M = static_cast<int32_t>(hidden_states.sizes()[0]);
66	    int32_t N = static_cast<int32_t>(hidden_states.sizes()[1]);
67	
68	    int32_t mNum = (M + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
69	    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, mNum));
70	    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;
71	
72	    at::Tensor y = at::empty_like(hidden_states);
73	
74	    // dtype flag: 0=fp32, 1=fp16, 2=bf16
75	    int64_t dtypeFlag = 0;
76	    if (hidden_states.scalar_type() == at::kHalf) {
77	        dtypeFlag = 1;
78	    } else if (hidden_states.scalar_type() == at::kBFloat16) {
79	        dtypeFlag = 2;
80	    }
81	
82	    // All tiling params as left values (required by EXEC_KERNEL_CMD)
83	    int32_t blockM = DEFAULT_BLOCK_M;
84	    float epsVal = static_cast<float>(eps);
85	    float invN = 1.0f / static_cast<float>(N);
86	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
87	
88	    EXEC_KERNEL_CMD(fused_add_rmsnorm, blockDim,
89	                    hidden_states, residual, weight, y,
90	                    M, N, blockM, usedCoreNum, tasksPerCore, epsVal, invN,
91	                    dtypeFlag);
92	
93	    return y;
94	}
95	
96	}  // namespace ascend_kernel
