11	// AscendC FusedAddRmsnorm — two-pass: sum of squares across N-tiles, then normalize
12	// Supports float32, float16, bfloat16
13	// NOTE: For fp32, we use ReinterpretCast on DeQue'd LocalTensor.
14	
15	#include "kernel_operator.h"
16	
17	constexpr int32_t BUFFER_NUM = 1;
18	constexpr int32_t TILE_N = 1024;
19	
20	template <typename T>
21	__aicore__ inline void LoadGmToUb(
22	    AscendC::LocalTensor<T> &dst, AscendC::GlobalTensor<T> src, uint32_t count)
23	{
24	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
25	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
26	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
27	}
28	
29	template <typename T>
30	__aicore__ inline void StoreUbToGm(
31	    AscendC::GlobalTensor<T> dst, AscendC::LocalTensor<T> &src, uint32_t count)
32	{
33	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
34	    AscendC::DataCopyPad(dst, src, copyParams);
35	}
36	
37	template <typename T>
38	__aicore__ inline AscendC::RoundMode OutputRoundMode()
39	{
40	    if constexpr (std::is_same_v<T, bfloat16_t>) {
41	        return AscendC::RoundMode::CAST_ROUND;
42	    }
43	    return AscendC::RoundMode::CAST_NONE;
44	}
45	
46	// =========================================================================
47	// FusedAddRmsnorm Kernel
48	// =========================================================================
49	
50	template <typename dataType>
51	class FusedAddRmsnormKernel {
52	public:
53	    __aicore__ inline void Init(
54	        GM_ADDR hidden_states, GM_ADDR residual, GM_ADDR weight, GM_ADDR y,
55	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
56	        int32_t tasksPerCore, float eps, float invN)
57	    {
58	        M_ = M; N_ = N; blockM_ = blockM; usedCoreNum_ = usedCoreNum;
59	        tasksPerCore_ = tasksPerCore; eps_ = eps; invN_ = invN;
60	
61	        hsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(hidden_states), static_cast<uint64_t>(M) * N);
62	        resGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(residual), static_cast<uint64_t>(M) * N);
63	        weightGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(weight), N);
64	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);
65	
66	        if ASCEND_IS_AIV { InitBuffers(); }
67	    }
68	
69	    __aicore__ inline void InitBuffers()
70	    {
71	        subBlockRows_ = blockM_ / AscendC::GetSubBlockNum();
72	        pipe_.InitBuffer(hsInQueue_, BUFFER_NUM, TILE_N * sizeof(dataType));
73	        pipe_.InitBuffer(resInQueue_, BUFFER_NUM, TILE_N * sizeof(dataType));
74	        pipe_.InitBuffer(weightInQueue_, BUFFER_NUM, TILE_N * sizeof(dataType));
75	        pipe_.InitBuffer(yOutQueue_, BUFFER_NUM, TILE_N * sizeof(dataType));
76	        pipe_.InitBuffer(reduceBuf_, TILE_N * sizeof(float));
77	        pipe_.InitBuffer(sumBuf_, 16 * sizeof(float));
78	        pipe_.InitBuffer(tempBuf_, TILE_N * sizeof(float));
79	        pipe_.InitBuffer(invRmsBuf_, sizeof(float));
80	        if constexpr (!std::is_same_v<dataType, float>) {
81	            pipe_.InitBuffer(hsCastBuf_, TILE_N * sizeof(float));
82	            pipe_.InitBuffer(resCastBuf_, TILE_N * sizeof(float));
83	            pipe_.InitBuffer(weightCastBuf_, TILE_N * sizeof(float));
84	            pipe_.InitBuffer(yCastBuf_, TILE_N * sizeof(float));
85	        }
86	    }
87	
88	    __aicore__ inline int32_t NumTiles() const { return (N_ + TILE_N - 1) / TILE_N; }
89	    __aicore__ inline int32_t GetValidN(int32_t c) const
90	    {
91	        return (c + TILE_N <= N_) ? TILE_N : (N_ - c);
92	    }
93	
94	    __aicore__ inline void Process()
95	    {
96	        if ASCEND_IS_AIV {
97	            const int ci = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
98	            const int si = AscendC::GetSubBlockIdx();
99	            for (int li = 0; li < tasksPerCore_; ++li) {
100	                const int bx = ci * tasksPerCore_ + li;
101	                int mBlk = (M_ + blockM_ - 1) / blockM_;
102	                if (bx >= mBlk) continue;
103	                for (int r = 0; r < subBlockRows_; ++r) {
104	                    int ri = bx * blockM_ + si * subBlockRows_ + r;
105	                    if (ri < M_) ProcessRow(ri);
106	                }
107	            }
108	        }
109	    }
110	
111	private:
112	    // ---- Copy ----
113	    __aicore__ inline void CopyInX(int32_t row, int32_t col, int32_t vN)
114	    {
115	        hsInL_ = hsInQueue_.AllocTensor<dataType>();
116	        resInL_ = resInQueue_.AllocTensor<dataType>();
117	        LoadGmToUb(hsInL_, hsGM_[static_cast<uint64_t>(row) * N_ + col], static_cast<uint32_t>(vN));
118	        LoadGmToUb(resInL_, resGM_[static_cast<uint64_t>(row) * N_ + col], static_cast<uint32_t>(vN));
119	        hsInQueue_.EnQue(hsInL_);
120	        resInQueue_.EnQue(resInL_);
121	    }
122	
123	    __aicore__ inline void CopyInW(int32_t col, int32_t vN)
124	    {
125	        wInL_ = weightInQueue_.AllocTensor<dataType>();
126	        LoadGmToUb(wInL_, weightGM_[col], static_cast<uint32_t>(vN));
127	        weightInQueue_.EnQue(wInL_);
128	    }
129	
130	    __aicore__ inline void CopyOutY(int32_t row, int32_t col, int32_t vN)
131	    {
132	        yOutL_ = yOutQueue_.DeQue<dataType>();
133	        StoreUbToGm(yGM_[static_cast<uint64_t>(row) * N_ + col], yOutL_, static_cast<uint32_t>(vN));
134	        yOutQueue_.FreeTensor(yOutL_);
135	    }
136	
137	    // ---- Cast Helpers ----
138	    __aicore__ inline void CastToFp32(AscendC::LocalTensor<float> &d, AscendC::LocalTensor<dataType> &s,
139	        AscendC::TBuf<AscendC::TPosition::VECCALC> &buf, int32_t cnt)
140	    {
141	        if constexpr (std::is_same_v<dataType, float>) {
142	            d = s.template ReinterpretCast<float>();
143	        } else {
144	            d = buf.Get<float>();
145	            AscendC::Cast(d, s, AscendC::RoundMode::CAST_NONE, cnt);
146	            AscendC::PipeBarrier<PIPE_V>();
147	        }
148	    }
149	
150	    __aicore__ inline void CastFromFp32(AscendC::LocalTensor<dataType> &d, AscendC::LocalTensor<float> &s, int32_t cnt)
151	    {
152	        if constexpr (!std::is_same_v<dataType, float>) {
153	            AscendC::Cast(d, s, OutputRoundMode<dataType>(), cnt);
154	            AscendC::PipeBarrier<PIPE_V>();
155	        }
156	    }
157	
158	    // ---- Pass 1: accumulate sum_sq across tiles ----
159	    __aicore__ inline float ComputeSumSq(int32_t row)
160	    {
161	        sumL_ = sumBuf_.Get<float>();
162	        reduceL_ = reduceBuf_.Get<float>();
163	        float sumSq = 0.0f;
164	
165	        for (int by = 0; by < NumTiles(); ++by) {
166	            int c0 = by * TILE_N, vN = GetValidN(c0);
167	            CopyInX(row, c0, vN);
168	
169	            hsInL_ = hsInQueue_.DeQue<dataType>();
170	            resInL_ = resInQueue_.DeQue<dataType>();
171	            CastToFp32(hsL_, hsInL_, hsCastBuf_, vN);
172	            CastToFp32(resL_, resInL_, resCastBuf_, vN);
173	
174	            tempL_ = tempBuf_.Get<float>();
175	            AscendC::Add(tempL_, hsL_, resL_, vN);          // x = hs + res
176	            AscendC::Mul(tempL_, tempL_, tempL_, vN);       // x^2
177	            AscendC::ReduceSum<float>(sumL_, tempL_, reduceL_, vN);
178	            sumSq += sumL_.GetValue(0);
179	
180	            hsInQueue_.FreeTensor(hsInL_);
181	            resInQueue_.FreeTensor(resInL_);
182	        }
183	        return sumSq;
184	    }
185	
186	    // ---- Compute inv_rms ----
187	    __aicore__ inline float ComputeInvRms(float sumSq)
188	    {
189	        sumL_ = sumBuf_.Get<float>();
190	        invRmsL_ = invRmsBuf_.Get<float>();
191	        AscendC::Duplicate(sumL_, sumSq * invN_ + eps_, 1);
192	        AscendC::Rsqrt(invRmsL_, sumL_, 1);
193	        AscendC::PipeBarrier<PIPE_ALL>();
194	        float ir = invRmsL_.GetValue(0);
195	        AscendC::PipeBarrier<PIPE_ALL>();
196	        return ir;
197	    }
198	
199	    // ---- Pass 2: normalize one tile ----
200	    __aicore__ inline void ComputeTile(float invRms, int32_t vN)
201	    {
202	        yOutL_ = yOutQueue_.AllocTensor<dataType>();
203	        hsInL_ = hsInQueue_.DeQue<dataType>();
204	        resInL_ = resInQueue_.DeQue<dataType>();
205	        wInL_ = weightInQueue_.DeQue<dataType>();
206	
207	        CastToFp32(hsL_, hsInL_, hsCastBuf_, vN);
208	        CastToFp32(resL_, resInL_, resCastBuf_, vN);
209	        CastToFp32(wL_, wInL_, weightCastBuf_, vN);
210	
211	        // Prepare output
212	        if constexpr (std::is_same_v<dataType, float>) {
213	            yL_ = yOutL_.template ReinterpretCast<float>();
214	        } else {
215	            yL_ = yCastBuf_.Get<float>();
216	        }
217	
218	        AscendC::Add(yL_, hsL_, resL_, vN);             // x = hs + res
219	        AscendC::Muls(yL_, yL_, invRms, vN);            // x * inv_rms
220	        AscendC::Mul(yL_, yL_, wL_, vN);                // x * weight
221	        CastFromFp32(yOutL_, yL_, vN);
222	
223	        hsInQueue_.FreeTensor(hsInL_);
224	        resInQueue_.FreeTensor(resInL_);
225	        weightInQueue_.FreeTensor(wInL_);
226	        yOutQueue_.EnQue(yOutL_);
227	    }
228	
229	    // ---- Process one row ----
230	    __aicore__ inline void ProcessRow(int32_t row)
231	    {
232	        float sumSq = ComputeSumSq(row);
233	        float invRms = ComputeInvRms(sumSq);
234	        for (int by = 0; by < NumTiles(); ++by) {
235	            int c0 = by * TILE_N, vN = GetValidN(c0);
236	            CopyInX(row, c0, vN);
237	            CopyInW(c0, vN);
238	            ComputeTile(invRms, vN);
239	            CopyOutY(row, c0, vN);
240	        }
241	    }
242	
243	    int32_t M_ = 0, N_ = 0, blockM_ = 0, usedCoreNum_ = 0;
244	    int32_t tasksPerCore_ = 0, subBlockRows_ = 0;
245	    float eps_ = 0.0f, invN_ = 0.0f;
246	
247	    AscendC::TPipe pipe_;
248	    AscendC::GlobalTensor<dataType> hsGM_, resGM_, weightGM_, yGM_;
249	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> hsInQueue_, resInQueue_, weightInQueue_;
250	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
251	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_, sumBuf_, tempBuf_, invRmsBuf_;
252	    AscendC::TBuf<AscendC::TPosition::VECCALC> hsCastBuf_, resCastBuf_, weightCastBuf_, yCastBuf_;
253	
254	    AscendC::LocalTensor<dataType> hsInL_, resInL_, wInL_, yOutL_;
255	    AscendC::LocalTensor<float> hsL_, resL_, wL_, yL_, reduceL_, sumL_, tempL_, invRmsL_;
256	};
257	
258	extern "C" __global__ __aicore__ void fused_add_rmsnorm(
259	    GM_ADDR hs, GM_ADDR res, GM_ADDR w, GM_ADDR y,
260	    int32_t M, int32_t N, int32_t bM, int32_t uC,
261	    int32_t tPC, float eps, float invN, int64_t dF)
262	{
263	    if (dF == 0) {
264	        FusedAddRmsnormKernel<float> k;
265	        k.Init(hs, res, w, y, M, N, bM, uC, tPC, eps, invN); k.Process();
266	    } else if (dF == 1) {
267	        FusedAddRmsnormKernel<half> k;
268	        k.Init(hs, res, w, y, M, N, bM, uC, tPC, eps, invN); k.Process();
269	    } else {
270	        FusedAddRmsnormKernel<bfloat16_t> k;
271	        k.Init(hs, res, w, y, M, N, bM, uC, tPC, eps, invN); k.Process();
272	    }
273	}
