// AscendC GaussianTopkSparseActivation — two-pass:
//   Pass 1: reduce sum & sum_sq across K-tiles → threshold = mean + std * ndtri
//   Pass 2: relu(X - threshold) → cast bfloat16 → write
// Supports input: float32, float16, bfloat16; output: always bfloat16

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t TILE_K = 1024;

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst, AscendC::GlobalTensor<T> src, uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst, AscendC::LocalTensor<T> &src, uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// Helper to load a scalar from GM into UB
template <typename T>
__aicore__ inline void LoadScalarToUb(
    AscendC::LocalTensor<T> &dst, AscendC::GlobalTensor<T> src)
{
    AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// =========================================================================
// GaussianTopkSparseActivation Kernel
// =========================================================================

template <typename dataType>
class GaussianTopkSparseActivationKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR ndtri_val, GM_ADDR y,
        int32_t M, int32_t K, int32_t blockM, int32_t usedCoreNum,
        int32_t tasksPerCore, float kRecip)
    {
        M_ = M; K_ = K; blockM_ = blockM; usedCoreNum_ = usedCoreNum;
        tasksPerCore_ = tasksPerCore; kRecip_ = kRecip;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(M) * K);
        ndtriGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(ndtri_val), 1);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ bfloat16_t *>(y), static_cast<uint64_t>(M) * K);

        if ASCEND_IS_AIV { InitBuffers(); }
    }

    __aicore__ inline void InitBuffers()
    {
        subBlockRows_ = blockM_ / AscendC::GetSubBlockNum();
        pipe_.InitBuffer(xInQueue_, BUFFER_NUM, TILE_K * sizeof(dataType));
        pipe_.InitBuffer(yOutQueue_, BUFFER_NUM, TILE_K * sizeof(bfloat16_t));
        pipe_.InitBuffer(reduceBuf_, TILE_K * sizeof(float));
        pipe_.InitBuffer(sumBuf_, 16 * sizeof(float));
        pipe_.InitBuffer(tempBuf_, TILE_K * sizeof(float));
        pipe_.InitBuffer(ndtriBuf_, sizeof(float));
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe_.InitBuffer(xCastBuf_, TILE_K * sizeof(float));
        }
    }

    __aicore__ inline int32_t NumTiles() const { return (K_ + TILE_K - 1) / TILE_K; }
    __aicore__ inline int32_t GetValidK(int32_t c) const
    {
        return (c + TILE_K <= K_) ? TILE_K : (K_ - c);
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int ci = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int si = AscendC::GetSubBlockIdx();
            for (int li = 0; li < tasksPerCore_; ++li) {
                const int bx = ci * tasksPerCore_ + li;
                int mBlk = (M_ + blockM_ - 1) / blockM_;
                if (bx >= mBlk) continue;
                for (int r = 0; r < subBlockRows_; ++r) {
                    int ri = bx * blockM_ + si * subBlockRows_ + r;
                    if (ri < M_) ProcessRow(ri);
                }
            }
        }
    }

private:
    // ---- Copy ----
    __aicore__ inline void CopyInX(int32_t row, int32_t col, int32_t vK)
    {
        xInL_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInL_, xGM_[static_cast<uint64_t>(row) * K_ + col], static_cast<uint32_t>(vK));
        xInQueue_.EnQue(xInL_);
    }

    __aicore__ inline void CopyOutY(int32_t row, int32_t col, int32_t vK)
    {
        yOutL_ = yOutQueue_.DeQue<bfloat16_t>();
        StoreUbToGm(yGM_[static_cast<uint64_t>(row) * K_ + col], yOutL_, static_cast<uint32_t>(vK));
        yOutQueue_.FreeTensor(yOutL_);
    }

    // ---- Cast Helpers ----
    __aicore__ inline void CastToFp32(AscendC::LocalTensor<float> &d, AscendC::LocalTensor<dataType> &s,
        AscendC::TBuf<AscendC::TPosition::VECCALC> &buf, int32_t cnt)
    {
        if constexpr (std::is_same_v<dataType, float>) {
            d = s.template ReinterpretCast<float>();
        } else {
            d = buf.Get<float>();
            AscendC::Cast(d, s, AscendC::RoundMode::CAST_NONE, cnt);
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

    __aicore__ inline void CastFromFp32(AscendC::LocalTensor<bfloat16_t> &d,
        AscendC::LocalTensor<float> &s, int32_t cnt)
    {
        AscendC::Cast(d, s, AscendC::RoundMode::CAST_ROUND, cnt);
        AscendC::PipeBarrier<PIPE_V>();
    }

    // ---- Pass 1: accumulate sum & sum_sq across K tiles, then compute threshold ----
    __aicore__ inline float ComputeThreshold(int32_t row, float ndtriLocal)
    {
        sumL_ = sumBuf_.Get<float>();
        reduceL_ = reduceBuf_.Get<float>();
        float sumVal = 0.0f, sumSqVal = 0.0f;

        int numTiles = NumTiles();
        for (int bk = 0; bk < numTiles; ++bk) {
            int c0 = bk * TILE_K, vK = GetValidK(c0);
            CopyInX(row, c0, vK);

            xInL_ = xInQueue_.DeQue<dataType>();
            CastToFp32(xL_, xInL_, xCastBuf_, vK);

            // reduce_sum over tile
            AscendC::ReduceSum<float>(sumL_, xL_, reduceL_, vK);
            sumVal += sumL_.GetValue(0);

            // x_sq = x * x
            tempL_ = tempBuf_.Get<float>();
            AscendC::Mul(tempL_, xL_, xL_, vK);

            // reduce_sum of squares
            AscendC::ReduceSum<float>(sumL_, tempL_, reduceL_, vK);
            sumSqVal += sumL_.GetValue(0);

            xInQueue_.FreeTensor(xInL_);
        }

        // mean = sum / K, mean_sq = sum_sq / K
        float meanVal = sumVal * kRecip_;
        float meanSqVal = sumSqVal * kRecip_;

        // var = max(0, mean_sq - mean^2)
        float meanSqDiff = meanVal * meanVal;
        float varVal = meanSqVal - meanSqDiff;
        if (varVal < 0.0f) varVal = 0.0f;

        // std = sqrt(var) — done via scalar path to avoid Sqrt 1-element UB issues
        float stdVal = (varVal > 0.0f) ? AscendC::sqrt(varVal) : 0.0f;

        // threshold = mean + std * ndtri
        return meanVal + stdVal * ndtriLocal;
    }

    // ---- Pass 2: apply relu(X - threshold), cast to bf16, write ----
    __aicore__ inline void ApplyThresholdAndWrite(int32_t row, float threshold)
    {
        int numTiles = NumTiles();
        for (int bk = 0; bk < numTiles; ++bk) {
            int c0 = bk * TILE_K, vK = GetValidK(c0);
            CopyInX(row, c0, vK);

            yOutL_ = yOutQueue_.AllocTensor<bfloat16_t>();
            xInL_ = xInQueue_.DeQue<dataType>();
            CastToFp32(xL_, xInL_, xCastBuf_, vK);

            // Prepare output float buffer
            yOutL_float_ = tempBuf_.Get<float>();

            // diff = X - threshold
            AscendC::Adds(yOutL_float_, xL_, -threshold, vK);

            // relu(diff)
            AscendC::Relu(yOutL_float_, yOutL_float_, vK);

            // cast float32 → bfloat16
            CastFromFp32(yOutL_, yOutL_float_, vK);

            xInQueue_.FreeTensor(xInL_);
            yOutQueue_.EnQue(yOutL_);
            CopyOutY(row, c0, vK);
        }
    }

    // ---- Process one row ----
    __aicore__ inline void ProcessRow(int32_t row)
    {
        // Load ndtri_val scalar into UB
        ndtriL_ = ndtriBuf_.Get<float>();
        LoadScalarToUb(ndtriL_, ndtriGM_[0]);
        AscendC::PipeBarrier<PIPE_ALL>();
        float ndtriLocal = ndtriL_.GetValue(0);
        AscendC::PipeBarrier<PIPE_ALL>();

        float threshold = ComputeThreshold(row, ndtriLocal);
        ApplyThresholdAndWrite(row, threshold);
    }

    int32_t M_ = 0, K_ = 0, blockM_ = 0, usedCoreNum_ = 0;
    int32_t tasksPerCore_ = 0, subBlockRows_ = 0;
    float kRecip_ = 0.0f;

    AscendC::TPipe pipe_;
    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<float> ndtriGM_;
    AscendC::GlobalTensor<bfloat16_t> yGM_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_, sumBuf_, tempBuf_, ndtriBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;

    AscendC::LocalTensor<dataType> xInL_;
    AscendC::LocalTensor<bfloat16_t> yOutL_;
    AscendC::LocalTensor<float> xL_, reduceL_, sumL_, tempL_, ndtriL_, yOutL_float_;
};

extern "C" __global__ __aicore__ void gaussian_topk_sparse_activation(
    GM_ADDR x, GM_ADDR ndtri_val, GM_ADDR y,
    int32_t M, int32_t K, int32_t bM, int32_t uC,
    int32_t tPC, float kRecip, int64_t dF)
{
    if (dF == 0) {
        GaussianTopkSparseActivationKernel<float> k;
        k.Init(x, ndtri_val, y, M, K, bM, uC, tPC, kRecip); k.Process();
    } else if (dF == 1) {
        GaussianTopkSparseActivationKernel<half> k;
        k.Init(x, ndtri_val, y, M, K, bM, uC, tPC, kRecip); k.Process();
    } else {
        GaussianTopkSparseActivationKernel<bfloat16_t> k;
        k.Init(x, ndtri_val, y, M, K, bM, uC, tPC, kRecip); k.Process();
    }
}
