// GaussianTopkSparseActivation op_host — tiling calculation + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_gaussian_topk_sparse_activation.h"

// ---------------------------------------------------------------------------
// Tiling constants
// ---------------------------------------------------------------------------

constexpr int32_t DEFAULT_BLOCK_M = 64;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

// ---------------------------------------------------------------------------
// Host function
// ---------------------------------------------------------------------------

namespace ascend_kernel {

at::Tensor gaussian_topk_sparse_activation(
    const at::Tensor &inputs,
    const at::Tensor &ndtri_val,
    double target_sparsity)
{
    // inputs: [M, K] where M = B * S, K = intermediate_size
    // ndtri_val: [1] float32 scalar pre-computed in Python
    TORCH_CHECK(inputs.dim() == 2, "inputs must be [M, K]");
    TORCH_CHECK(ndtri_val.numel() == 1, "ndtri_val must be a 1-element tensor");
    TORCH_CHECK(
        inputs.scalar_type() == at::kFloat ||
        inputs.scalar_type() == at::kHalf ||
        inputs.scalar_type() == at::kBFloat16,
        "inputs must be float32, float16, or bfloat16");
    TORCH_CHECK(inputs.is_contiguous(), "inputs must be contiguous");
    TORCH_CHECK(ndtri_val.scalar_type() == at::kFloat, "ndtri_val must be float32");

    int32_t M = static_cast<int32_t>(inputs.sizes()[0]);
    int32_t K = static_cast<int32_t>(inputs.sizes()[1]);

    // target_sparsity == 0.0: short-circuit, copy input to bf16 output directly
    if (target_sparsity == 0.0) {
        return inputs.to(at::kBFloat16);
    }

    int32_t mNum = (M + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, mNum));
    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;

    // Output is always bfloat16
    at::Tensor y = at::empty({M, K}, inputs.options().dtype(at::kBFloat16));

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (inputs.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (inputs.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // All tiling params as left values (required by EXEC_KERNEL_CMD)
    int32_t blockM = DEFAULT_BLOCK_M;
    float kRecip = 1.0f / static_cast<float>(K);
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(gaussian_topk_sparse_activation, blockDim,
                    inputs, ndtri_val, y,
                    M, K, blockM, usedCoreNum, tasksPerCore, kRecip,
                    dtypeFlag);

    return y;
}

}  // namespace ascend_kernel
